-- Comentarios do CTN, lote 8 (arts. 169 a 186). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 169 and 186 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(169,'','Prescrição da ação anulatória da decisão que denega a restituição','Prescreve em dois anos a ação anulatória da decisão administrativa que denegar a restituição. O parágrafo único dispõe que o prazo de prescrição é interrompido pelo início da ação judicial, recomeçando o seu curso, por metade, a partir da data da intimação validamente feita ao representante judicial da Fazenda Pública interessada.'),
(170,'','Compensação','A lei pode, nas condições e sob as garantias que estipular, ou cuja estipulação em cada caso atribuir à autoridade administrativa, autorizar a compensação de créditos tributários com créditos líquidos e certos, vencidos ou vincendos, do sujeito passivo contra a Fazenda Pública; o texto traz a anotação "Vide Decreto nº 7.212, de 2010". O parágrafo único dispõe que, sendo vincendo o crédito do sujeito passivo, a lei determinará a apuração do seu montante, não podendo cominar redução maior que a correspondente ao juro de 1% (um por cento) ao mês pelo tempo a decorrer entre a data da compensação e a do vencimento.'),
(170,'Art. 170-A','Vedação de compensação antes do trânsito em julgado','É vedada a compensação mediante o aproveitamento de tributo, objeto de contestação judicial pelo sujeito passivo, antes do trânsito em julgado da respectiva decisão judicial (artigo incluído pela Lei Complementar n. 104, de 2001).'),
(171,'','Transação','A lei pode facultar, nas condições que estabeleça, aos sujeitos ativo e passivo da obrigação tributária celebrar transação que, mediante concessões mútuas, importe em determinação de litígio e consequente extinção de crédito tributário. O parágrafo único dispõe que a lei indicará a autoridade competente para autorizar a transação em cada caso.'),
(171,'Art. 171-A','Arbitragem especial tributária e aduaneira','Lei especial autorizará a arbitragem especial tributária e aduaneira, com vistas a promover a solução de controvérsias e a resolução do contencioso tributário e aduaneiro administrativo e judicial (Lei Complementar n. 236, de 2026). O parágrafo único dispõe que a sentença arbitral será vinculante e produzirá os mesmos efeitos que a decisão judicial.'),
(171,'Art. 171-B','Mediação de controvérsias tributárias e aduaneiras','Lei estabelecerá os critérios e as condições para a mediação de controvérsias tributárias e aduaneiras, a ser exercida por terceiro sem poder decisório, que, escolhido ou aceito pelas partes, as auxiliará e as estimulará na identificação ou na construção de soluções consensuais (Lei Complementar n. 236, de 2026).'),
(171,'Art. 171-C','Transação, mediação e arbitragem e renúncia de receita','A transação, a mediação e a arbitragem especial tributária e aduaneira não caracterizam renúncia de receita para fins do disposto no art. 14 da Lei Complementar n. 101, de 4 de maio de 2000 (Lei de Responsabilidade Fiscal), na redação incluída pela Lei Complementar n. 236, de 2026.'),
(172,'','Remissão','A lei pode autorizar a autoridade administrativa a conceder, por despacho fundamentado, remissão total ou parcial do crédito tributário, atendendo à situação econômica do sujeito passivo (inciso I); ao erro ou ignorância escusáveis do sujeito passivo, quanto a matéria de fato (inciso II); à diminuta importância do crédito tributário (inciso III); a considerações de equidade, em relação com as características pessoais ou materiais do caso (inciso IV); e a condições peculiares a determinada região do território da entidade tributante (inciso V). O parágrafo único dispõe que o despacho não gera direito adquirido, aplicando-se, quando cabível, o disposto no art. 155.'),
(173,'','Decadência','O direito de a Fazenda Pública constituir o crédito tributário extingue-se após 5 (cinco) anos, contados do primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado (inciso I) e da data em que se tornar definitiva a decisão que houver anulado, por vício formal, o lançamento anteriormente efetuado (inciso II). O parágrafo único dispõe que o direito extingue-se definitivamente com o decurso do prazo nele previsto, contado da data em que tenha sido iniciada a constituição do crédito tributário pela notificação, ao sujeito passivo, de qualquer medida preparatória indispensável ao lançamento.'),
(174,'','Prescrição da ação de cobrança','A ação para a cobrança do crédito tributário prescreve em cinco anos, contados da data da sua constituição definitiva. O § 1º, renumerado pela Lei Complementar n. 236, de 2026, dispõe que a prescrição se interrompe pelo despacho do juiz que ordenar a citação em execução fiscal (inciso I); pelo protesto extrajudicial da certidão de dívida ativa ou pelo protesto judicial (inciso II); por qualquer ato judicial que constitua em mora o devedor (inciso III); por qualquer ato inequívoco, ainda que extrajudicial, que importe em reconhecimento do débito pelo devedor (inciso IV); pela instauração do procedimento de mediação, nos termos da legislação específica (inciso V); pela instituição da arbitragem especial tributária e aduaneira, retroagindo à data do requerimento de submissão da controvérsia à arbitragem (inciso VI); pela sentença de extinção da execução fiscal nos casos de não localização do executado ou de bens passíveis de constrição, desde que a prescrição intercorrente ainda não se tenha iniciado (inciso VII); pela informação do crédito na falência ou liquidação extrajudicial do sujeito passivo, ficando o prazo suspenso até o encerramento do processo, nos termos da legislação específica (inciso VIII); e pelo ato inicial da execução fiscal extrajudicial, nos termos da legislação específica (inciso IX). O § 3º dispõe que a prescrição interrompida recomeça a correr da data do ato que a interrompeu, ou do último ato do processo judicial ou extrajudicial para a interromper. Os §§ 2º e 4º constam como vetados e estão registrados como não vigentes.'),
(175,'','Exclusão do crédito tributário','Excluem o crédito tributário a isenção (inciso I) e a anistia (inciso II). O parágrafo único dispõe que a exclusão do crédito tributário não dispensa o cumprimento das obrigações acessórias dependentes da obrigação principal cujo crédito seja excluído, ou dela consequentes.'),
(176,'','Isenção: requisitos','A isenção, ainda quando prevista em contrato, é sempre decorrente de lei que especifique as condições e requisitos exigidos para a sua concessão, os tributos a que se aplica e, sendo caso, o prazo de sua duração. O parágrafo único dispõe que a isenção pode ser restrita a determinada região do território da entidade tributante, em função de condições a ela peculiares.'),
(177,'','Isenção: extensão','Salvo disposição de lei em contrário, a isenção não é extensiva às taxas e às contribuições de melhoria (inciso I) e aos tributos instituídos posteriormente à sua concessão (inciso II).'),
(178,'','Isenção: revogação ou modificação','A isenção, salvo se concedida por prazo certo e em função de determinadas condições, pode ser revogada ou modificada por lei, a qualquer tempo, observado o disposto no inciso III do art. 104 (redação dada pela Lei Complementar n. 24, de 1975).'),
(179,'','Isenção: efetivação por despacho','A isenção, quando não concedida em caráter geral, é efetivada, em cada caso, por despacho da autoridade administrativa, em requerimento com o qual o interessado faça prova do preenchimento das condições e do cumprimento dos requisitos previstos em lei ou contrato para sua concessão. O § 1º dispõe que, tratando-se de tributo lançado por período certo de tempo, o despacho será renovado antes da expiração de cada período, cessando automaticamente os seus efeitos a partir do primeiro dia do período para o qual o interessado deixar de promover a continuidade do reconhecimento da isenção. O § 2º dispõe que o despacho não gera direito adquirido, aplicando-se, quando cabível, o disposto no art. 155.'),
(180,'','Anistia: alcance','A anistia abrange exclusivamente as infrações cometidas anteriormente à vigência da lei que a concede, não se aplicando aos atos qualificados em lei como crimes ou contravenções e aos que, mesmo sem essa qualificação, sejam praticados com dolo, fraude ou simulação pelo sujeito passivo ou por terceiro em benefício daquele (inciso I) e, salvo disposição em contrário, às infrações resultantes de conluio entre duas ou mais pessoas naturais ou jurídicas (inciso II).'),
(181,'','Anistia: modalidades','A anistia pode ser concedida em caráter geral (inciso I) ou limitadamente: às infrações da legislação relativa a determinado tributo (inciso II, alínea a); às infrações punidas com penalidades pecuniárias até determinado montante, conjugadas ou não com penalidades de outra natureza (alínea b); a determinada região do território da entidade tributante, em função de condições a ela peculiares (alínea c); e sob condição do pagamento de tributo no prazo fixado pela lei que a conceder, ou cuja fixação seja atribuída pela mesma lei à autoridade administrativa (alínea d).'),
(182,'','Anistia: efetivação por despacho','A anistia, quando não concedida em caráter geral, é efetivada, em cada caso, por despacho da autoridade administrativa, em requerimento com o qual o interessado faça prova do preenchimento das condições e do cumprimento dos requisitos previstos em lei para sua concessão. O parágrafo único dispõe que o despacho não gera direito adquirido, aplicando-se, quando cabível, o disposto no art. 155.'),
(183,'','Garantias do crédito tributário: rol não exaustivo','A enumeração das garantias atribuídas no Capítulo ao crédito tributário não exclui outras que sejam expressamente previstas em lei, em função da natureza ou das características do tributo a que se refiram. O parágrafo único dispõe que a natureza das garantias atribuídas ao crédito tributário não altera a natureza deste nem a da obrigação tributária a que corresponda.'),
(184,'','Responsabilidade patrimonial pelo crédito tributário','Sem prejuízo dos privilégios especiais sobre determinados bens, que sejam previstos em lei, responde pelo pagamento do crédito tributário a totalidade dos bens e das rendas, de qualquer origem ou natureza, do sujeito passivo, seu espólio ou sua massa falida, inclusive os gravados por ônus real ou cláusula de inalienabilidade ou impenhorabilidade, seja qual for a data da constituição do ônus ou da cláusula, excetuados unicamente os bens e rendas que a lei declare absolutamente impenhoráveis.'),
(185,'','Presunção de fraude na alienação ou oneração de bens','Presume-se fraudulenta a alienação ou oneração de bens ou rendas, ou seu começo, por sujeito passivo em débito para com a Fazenda Pública, por crédito tributário regularmente inscrito como dívida ativa (redação dada pela Lei Complementar n. 118, de 2005). O parágrafo único dispõe que o artigo não se aplica na hipótese de terem sido reservados, pelo devedor, bens ou rendas suficientes ao total pagamento da dívida inscrita.'),
(185,'Art. 185-A','Indisponibilidade de bens e direitos','Na hipótese de o devedor tributário, devidamente citado, não pagar nem apresentar bens à penhora no prazo legal e não forem encontrados bens penhoráveis, o juiz determinará a indisponibilidade de seus bens e direitos, comunicando a decisão, preferencialmente por meio eletrônico, aos órgãos e entidades que promovem registros de transferência de bens, especialmente ao registro público de imóveis e às autoridades supervisoras do mercado bancário e do mercado de capitais, a fim de que, no âmbito de suas atribuições, façam cumprir a ordem judicial. O § 1º dispõe que a indisponibilidade limitar-se-á ao valor total exigível, devendo o juiz determinar o imediato levantamento da indisponibilidade dos bens ou valores que excederem esse limite. O § 2º dispõe que os órgãos e entidades comunicados enviarão imediatamente ao juízo a relação discriminada dos bens e direitos cuja indisponibilidade houverem promovido.'),
(186,'','Preferências do crédito tributário','O crédito tributário prefere a qualquer outro, seja qual for sua natureza ou o tempo de sua constituição, ressalvados os créditos decorrentes da legislação do trabalho ou do acidente de trabalho (redação dada pela Lei Complementar n. 118, de 2005). O parágrafo único dispõe que, na falência, o crédito tributário não prefere aos créditos extraconcursais ou às importâncias passíveis de restituição, nos termos da lei falimentar, nem aos créditos com garantia real, no limite do valor do bem gravado (inciso I); a lei poderá estabelecer limites e condições para a preferência dos créditos decorrentes da legislação do trabalho (inciso II); e a multa tributária prefere apenas aos créditos subordinados (inciso III).')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
